; Huffman-compressed text group(s): $1B
; Text $0360: The lock doesn't turn.
; Text $0361: There's no key.
; Text $0362: 'I see you've brought what we want.Give it to me now!'
; Text $0363: 'I got it! Here's the Princess.Bye!'
; Text $0364: 'Don't you want the Princess back alive? Give it to me!'
; Text $0365: 'Thanks for rescuing me.I've learned a lesson.'<4F>I'm not really a princess.My name is May.I'm just an actress.'<4F>I got carried away because people treated me nicely when I pretended to be a princess....'
; Text $0366: 'I'll join my companions now.'<4F>It's not much,but I'll give you this Thief's Key.'<44>
; Text $0367: Thereafter,the fake princess,May,and her companions disappeared.<44>And a new day began....
; Text $0368: 'The King says you can pass now.'
; Text $0369: 'Be very careful on your journey.'
; Text $036A: Reed:'You can't carry any more things.Come back after selling or discarding some.'
; Text $036B: Neta:'Welcome home,darling.Have you brought more merchandise?'
; Text $036C: Neta:'Then come over here....'
; Text $036D: Neta:'Before receiving the merchandise,I'll give you the proceeds from yesterday's sales.'<44>Taloon receives <47> gold piece<4C>!<44>
; Text $036E: Neta:'What shall I put up for sale?'
; Text $036F: Neta:'The <48>? I'll sell it for <47> gold piece<4C>! Is that OK?'
; Text $0370: Neta:'Alright,I'll put it up for sale.'<44>
; Text $0371: Neta:'Anything else for sale?'
; Text $0372: Neta:'You don't want to sell it? Keep it then.'<44>
; Text $0373: Neta:'I think the <48> is too valuable to sell.You'd better keep it.'<44>
; Text $0374: Neta:'We're through stocking,right? Would you like to see what we have for sale?'
; Text $0375: Neta:'I'll try hard to get good prices.You work hard too.Smack!'
; Text $0376: Neta:'We don't have any merchandise! Bring some soon.'
; Text $0377: Neta:'I'm sorry....'<44>Neta:'I haven't been able to keep up with you.Our inventory is full.'<44>Neta:'Would you like to see what we have for sale?'
; Text $0378: Strom:'My 5 days have passed.I'll leave now.'<44>Strom:'Take care! Bye!'
; Text $0379: Laurent:'Sorry,my 5 days have passed.I must go.Farewell!'
; Text $037A: <49> pushes the button on the wall.<44>The door opens.
; Text $037B: <49> puts the treasure back where it was.
; Text $037C: Thus Taloon left for the east in search of legendary weapons and treasures.<44>To collect every weapon and to become the world's greatest arms merchant was his dream.
; Text $037D: 'Yeek! You're humans.Lita,we're leaving now!'<4F>Yes,sister.'<4F>Oops,I dropped the medicine!'<4F>Don't worry about it.Hurry!'
; Text $037E: Cristo:'Princess,I'll cheer you on from here.'
; Text $037F: Brey:'The best of luck to you!'
