; Text $0380: King:'Welcome,Princess Alena! You must defeat 5 opponents to go on to the final match!'<44>King:'Necrosaro is the only one who has defeated 5 opponents so far.'<44>King:'Good luck!'
; Text $0381: 'Princess Alena defeated <50>!'<44>
; Text $0382: 'The next opponent is <50>!'
; Text $0383: 'Princess Alena has defeated 5 opponents!'<44>King:'Congratulations,Princess Alena!'<44>King:'The final match is next.Call Necrosaro.'
; Text $0384: King:'Where is he? Bring Necrosaro now!'
; Text $0385: King:'What? Necrosaro is missing? Hmm....'<44>King:'.........'<44>King:'We can't wait for him forever.'<44>King:'I declare Princess Alena the winner of this tournament!'
; Text $0386: Brey:'Princess,good going!'
; Text $0387: Cristo:'Princess Alena,congratulations on your victory!'
; Text $0388: Brey:'How strange! What happened?'
; Text $0389: Cristo:'Where's everybody? Hello? Is anyone here?'<44><4E>But there was no reply....
; Text $038A: 'There's a slot machine? Will you play?'
; Text $038B: What did the dreams of the King of Santeem mean?<43>...the mysterious Necrosaro,why did he suddenly disappear?<44>...and what befell the people of Santeem?<44>Determined to solve these mysteries,Princess Alena's Party embarked on another journey....
; Text $038C:
; Text $038D: 'That's worth <47> gold piece<4C>.Is that alright?'
; Text $038E: 'You've come to the Castle so late at night.'<4F>I can't allow you here.Leave now!'
; Text $038F: 'Princess Alena,return to Santeem Castle immediately! G <4B>Gasp!'<51>
; Text $0390: Alena kicks through the wall.
; Text $0391:   Congratulations!<43>    Prince Reed<43>        and<43>   Princess Mia!
; Text $0392: A voice is heard out of nowhere....<44><4E>'Chosen Ones. It's not the time to   give up.'<44><4E>'I shall revive you. Open your eyes....'<44>
; Text $0393:
; Text $0394: There was a small,nameless village deep in the mountains far east of Endor.<44>The villagers lived quietly.They never left the village or let outsiders enter.<44>Only the villagers were supposed to know of the village's existence.<43>But...<44>
; Text $0395: 'It's done.'
; Text $0396: '<49>,my dear child.Take this lunch to your father at the pond.He's fishing.'<4F>Greet everyone you pass,OK?'
; Text $0397: 'Monsters finally found this village! They'll be here any second!'
; Text $0398: 'Oh,no! <49>,flee now! Don't worry about me.'
; Text $0399: 'Follow me!'
; Text $039A: 'We'll stop the monsters! Take <49> to a safe place!'
; Text $039B: Celia:'<49>! If anything happens to you,I....'<44>Celia:'Hide! Hurry! I'll be there soon!'
; Text $039C: 'Those monsters! They found <49>!'<4F>We only needed a little more time to make <49> the great Hero.'<4F>This way,<49>! Come!'
; Text $039D: 'Yahoo!'<43><4B>'Shake more!'<43><4B>'Ahooo!'<43><4B>
; Text $039E: <49> checked inside the jar.<44>
; Text $039F: There were stairs.
