; Huffman-compressed text group(s): $1D
; Text $03A0: Mia:'Oh,Reed! I have to tell my father! Father!'
; Text $03A1: King:'I heard the news,Mia.'<44>King:'You do not need to worry.'<44>King:'Taloon is the name,isn't it? Would you take this scroll to the King of Bonmalmo?'<44>Taloon receives the Royal Scroll!<43><56><44>King:'Please hurry.'
; Text $03A2: Taloon reads the Royal Scroll.<4F>Dear Friend,<43>   King of Bonmalmo:<43>Please listen to what I must say.'<4F>It appears that my daughter,Mia,and your son,Reed,are in love.'<4F>They don't have to marry now,but I do look forward to their marriage....<43>   The King of Endor'<44>
; Text $03A3: But the King of Bonmalmo isn't here!
; Text $03A4: King:'Oh,is that so?'<44>King:'If my son,Reed,marries the Princess of Endor,he'll be the next king of Endor.'<44>King:'I won't have to invade Endor.'<44>King:'I appreciate what you've done.I'll dispatch a messenger right away.You can go now.'
; Text $03A5: It's locked!<44>But Orin breaks the lock.
; Text $03A6: 'What a failure,Balzack! What can we tell Necrosaro?'<43><4B>
; Text $03A7: Balzack:'Keeleon,please don't tell this to Necrosaro.'<44>Keeleon:'Don't worry.I can't let you die now.'<44>Keeleon:'You,Edgar's daughters! Come! I'll fight you.'
; Text $03A8: 'Are you awake? You were terribly injured.Cough...Cough...'
; Text $03A9: 'A jailbreak!'<44>Orin:'They've found us! Hurry!'
; Text $03AA: Orin:'I'll stop them.Run! Now!'
; Text $03AB: 'The ship arrived at Endor!'
; Text $03AC: This is how Mara and Nara,without fulfilling their wish,left their home country.<44>What are the small lights which will help them?<44>Their new journey to search for them has just begun.
; Text $03AD: 'Tov,always obey Taloon.'
; Text $03AE: Tom:'I'm finally here.Thanks.This is for you.'<44><4E>Taloon receives <47> gold piece<4C>!
; Text $03AF: '<49>,you're already strong!'<44>
; Text $03B0: 'Prince,you shouldn't talk with such a lowly commoner!'
; Text $03B1: 'Leave now!'
; Text $03B2: 'I'm da Gardi.What happened?'<4F>When I woke up,the village was gone....'<4F>That's right!'<4F>I was supposed to go to Bonmalmo Castle....I have to go now.Excuse me!'
; Text $03B3: There's a button.Do you want to push it?
; Text $03B4: 'Welcome back,<49>!'<44>
; Text $03B5: <49> checks inside the drawer.<44>
; Text $03B6: <49> checks the book shelf.<44>
; Text $03B7: No important books are found.
; Text $03B8: <49> reads the sign post.<44>
; Text $03B9: <49> obtains <47> gold piece<4C>.
; Text $03BA: <49>'s Party obtains <47> gold piece<4C>.
; Text $03BB: <49>,not being one of the Chosen Ones,doesn't know what to do!<44>
; Text $03BC: Can't move this way!<44>
; Text $03BD: Use TACTICS Command to change members.
; Text $03BE: The story up to this point will be saved on the Imperial Scrolls of Honor.Is that alright?
; Text $03BF: If you don't save,you'll begin from the last point you saved in Chapter <47> again.Is that alright?
