; Text $03C0:  <49>,<49>,<43> <49>,<49>,<43><40>
; Text $03C1:  <49>,<49>,<43> <49>,<43><40>
; Text $03C2: <44>'It seems I can't be equipped with this.'
; Text $03C3: <44>'It seems I can be equipped with this.'
; Text $03C4: !
; Text $03C5: 'Over here is a weapon shop and an armor shop.You can buy your equipment here.'
; Text $03C6: Taloon:'Now let's head south!'<44>Taloon:'I hear an old sea expert who has a valuable map lives in the Town of Mintos down south.'<43><4B>
; Text $03C7: Taloon:'Oh! I don't know who you are,but you've come at right time!'<44>Taloon:'I want to extinguish the Evil Fire burning in this lighthouse.'<44>Taloon:'But powerful monsters have been preventing me from going any farther.'<44>Taloon:'Will you extinguish the Evil Fire for me?'
; Text $03C8: Taloon:'I beg you,please!'
; Text $03C9: Taloon:'I thank you!'<44>
; Text $03CA: Taloon:'The Fire of Serenity burned in this lighthouse until recently.'<44>Taloon:'They say a remnant of it still burns somewhere in this lighthouse.'<44>Taloon:'It should be able to extinguish the Evil Fire.'<44>Taloon:'Shall I repeat this?'
; Text $03CB: <49>,paralyzed,can't move.
; Text $03CC: <49> checks the oven.<44>
; Text $03CD: <49> checks the sink.<44>
; Text $03CE: <49> checks the grave.<44>
; Text $03CF: '<49> now has...'<4F>no coin.'<4F>When you have coins,come back.'
; Text $03D0:    The Tournament<43>     Held Now!
; Text $03D1:      Dangerous!<43>     Stay Away!
; Text $03D2:        WANTED!<43>  The Gas Canister!<43><41>        The Item Shop
; Text $03D3:   A Desert Bazaar<43>     Now Open!
; Text $03D4:      The Winner of<43>    The Tournament:<43><41>     Princess Alena!
; Text $03D5:    Wait a Minute!<43> You Need to Upgrade<43>   Your Equipment!<43><41>     Surene's Guild of<43>     Arms Merchants
; Text $03D6: 'Zenithian Castle is high up in the sky.Master Dragon lives there.'<4F>Master Dragon is so strong.Long ago,he imprisoned the Ruler of Evil in darkness.'<4F>I think the people of Stancia in the northern sea can tell you more about Zenithian Castle.'
; Text $03D7:      Keep off<43>  the Flower Bed!
; Text $03D8:   The House of Edgar,<43>      Alchemist
