; Text $03E0: 'Listen well,<49>.The monsters seek to end your life! You are a threat to them.'<4F>Born with a hidden power,you have the potential to become strong enough to destroy any evil being.'<4F>But you're still weak.Escape and survive! Understand?'
; Text $03E1: Celia:'<49>....I've enjoyed growing up with you....'<44>
; Text $03E2: Celia:'<49>,you're so cute I've always thought of you as my little sister....'<44>
; Text $03E3: Celia:'Don't worry.I won't let them take your life.'<44>
; Text $03E4: Celia chants Transform.
; Text $03E5: Celia transforms into an exact replica of <49>!<44>Celia:'Goodbye,<49>....'
; Text $03E6: The monsters' voices are heard from outside.<44>'Necrosaro,we've destroyed <49> the Hero!'<44>Necrosaro:'Well done! Everyone,return to our base!'
; Text $03E7: 'Kekiki! Burn! <4B>Burn!'<4F>The Evil Fire will sink all the ships.Kekiki!'<4F>Ha! <4B>Who's there?'
; Text $03E8: 'Kekiki! You fools!'<4F>You've come at the right moment.I'll throw you into this Evil Fire as kindling! Kekiki!'
; Text $03E9: <49> throws the <48> in the fire!
; Text $03EA: There's a button on the bottom of the treasure chest! Do you want to push it?
; Text $03EB: Moreover<44>
; Text $03EC: The door looks sturdy,but it might break with the combined force of 3 people!
; Text $03ED: Alena:'You found the Padequia Root?'<44>Alena:'I couldn't find it myself and returned empty handed.I'm grateful!'<44>
; Text $03EE: Alena:'Quick! Cristo needs the Padequia!'
; Text $03EF: <49> grinds the Padequia Root and gives it to Cristo!<44>
; Text $03F0: 'Please wait! I'm sorry but I eavesdropped on your conversation.'<4F>I didn't know that <49> was the Hero who will save the world!'<44>
; Text $03F1: 'A man named Ragnar,searching for the Hero,once stayed at this inn.'<4F>Ragnar said he was going to a country named Keeleon in the far west....'
; Text $03F2: This door doesn't seem to open.
; Text $03F3: 'You've come to save us!'<4F>We've been waiting for you...'<4F>to fall into the Evil World!'
; Text $03F4: But the strange force works and contains <50>!
; Text $03F5: Nara:'Help!'
; Text $03F6: The monster chants Return!
; Text $03F7: Mara:'<49>,you've come to rescue us! That's what you thought I would say....'<44>Mara:'You won't fool us again.You're not <49>! We'll fight you this time!'<44>Nara:'Wait sis! I think this is really <49>.I can tell.'<44>
; Text $03F8: Mara:'Really? Then answer this.Was Nara at the Casino in Endor?'
; Text $03F9: Mara:'I was right! This is a monster!'<44>Nara:'I still think it's <49>.<43><49>,it's you,isn't it?'<44>
; Text $03FA: Mara:'Hmm...you may be right.'<44>Nara:'Sorry we doubted you.We've been chased by your imposter for so long....'<44>Mara:'Let's go now!'
; Text $03FB: <49> can't be equipped with any more things.
; Text $03FC: 'Congratulations! You're the 1000th person to travel through this tunnel since its opening!'<4F>You'll receive a terrific prize from the King of Endor.'<4F>It's 2000 coins you can use at the Casino in Endor!'<44>
; Text $03FD: 'It'll be deposited at the Casino under your name! Congratulations!'
; Text $03FE:        North to<43> The Village of Kievs
; Text $03FF: The Evil Fire ceases and the Fire of Serenity starts burning!
