; Huffman-compressed text group(s): $20
; Text $0400: Soldier:'Quiet!'<44>Ragnar:'You can't stop me!'
; Text $0401: Ragnar:'Aren't you the Hero's companions?'<44>Ragnar:'I want to see the Hero now!'
; Text $0402: Ragnar:'I've finally found the Hero I've been searching for!'<44>Ragnar:'You fit the description I heard at the House of Prophecy!'<44>Ragnar:'I hear the ones in this room belong to the evil force which plans to destroy the world.'<44>Ragnar:'Let's defeat them and reveal the source of evil which drives them!'<44>Ragnar:'Let's go inside!'
; Text $0403: Soldier:'Intruders!'
; Text $0404: Ragnar:'I'll handle them! You take care of the monster!'
; Text $0405: 'I...I'm defeated....Who are you?'<4F>Are you the Hero who is prophesied to destroy the Ruler of Evil?'<4F>You can't be! I heard Necrosaro destroyed the Hero....<4B>Gasp!'<43><4B><51>
; Text $0406: 'It...<4B>It's impossible! My body,supposedly invincible,is terribly wounded....'<4F>But as long as the Secret of Evolution exists,I will never fall....I will...I will...<4B>Gasp!'<43><4B>
; Text $0407: 'The experiment seems to have failed.We must report to Necrosaro....'
; Text $0408: 'The Golden Bracelet is necessary to perfect the Secret of Evolution.'<4F>It's said the Golden Bracelet amplifies the evil force!'
; Text $0409: 'When we obtain the Golden Bracelet and perfect the Secret of Evolution...'<4F>our time,the time of the evil force,will come! Ha,Ha,Ha!'
; Text $040A: 'Nooo! Monsters!'
; Text $040B: 'Yeek! Get away from me!'
; Text $040C: 'You monsters! I'll take care of you!'
; Text $040D: 'Auugh! My end has come!'
; Text $040E: 'Yuk! Help!'
; Text $040F: 'What are you?'
; Text $0410: 'I'm not afraid of monsters!'
; Text $0411: 'Oh,my...Fuuf!'
; Text $0412: 'Oh,no! Monsters are in the town! This is the end!'
; Text $0413: 'You bold monsters! Come!'
; Text $0414: 'Eiiyaa! Monsters!'
; Text $0415: 'Monsters! Help! Someone,help!'
; Text $0416: 'Someone,help me!'
; Text $0417: 'Don't come near me!'
; Text $0418: 'Yiee! I have some money.Spare me!'
; Text $0419: 'Don't come any closer or I'll bash you!'
; Text $041A: 'Garrru!'
; Text $041B: 'Gyanyanya!'
; Text $041C: 'Snrrt!'
; Text $041D: 'You! Bonk,Bonk...'
; Text $041E: 'Uh! I...I'd better run!'
; Text $041F: 'Please spare us!'
