; Huffman-compressed text group(s): $21
; Text $0420: 'Ooops!'
; Text $0421: Panon:'Well,seems my task is over.'<44>Panon:'I'll resume my wandering.'<44>Panon:'Goodbye,<49>.I wish you success!'<44>
; Text $0422: Panon left the Party!
; Text $0423: 'A monster!'<4F>Huh? <4B>Healie is the name?'<4F>Sorry but I can't sell you anything....'
; Text $0424: <49> doesn't seem to want to carry it.
; Text $0425: 'No way!'<4F>I don't deal with monsters!'
; Text $0426: <49> doesn't seem to want to sell it.
; Text $0427: 'Bye....'
; Text $0428: Cristo's complexion returns to normal at once,and he recovers!<44>Cristo:'Umm...Ha! <4B>Princess!'
; Text $0429: 'You may wager these winnings on the next match.Do you want to?'
; Text $042A: But the King is asleep....
; Text $042B: 'But you don't seem to be able to carry that much money.'
; Text $042C: '<49> should return to the wagon.'
; Text $042D: <44>'1 coin costs <47> gold piece<4C>.How many do you want?'
; Text $042E: 'Wait a second! You can't travel like that.'<4F>You'd better take the things from those jars in that room!'
; Text $042F: <44>Alena:'You're fine,Cristo.'<44>Cristo:'I'm ashamed.I'm the one who should be looking after you.'<44>Alena:'Don't worry,Cristo.Now let's resume our journey to find Necrosaro!'<44>
; Text $0430: Alena:'What's the matter? <4B>Huh? <4B><49> too...Necrosaro....'<44>
; Text $0431: 'I need to make sure.'<4F>The Imperial Scrolls of Honor won't be updated.Do you still want to end?'
; Text $0432:
; Text $0433: 'If that's the case,continue your quest.'<44>
; Text $0434: <49> has fallen into a deep sleep....<43>Seems to have begun dreaming....<4B><4B>
; Text $0435: <4E>Saro:'Rosa,have you<43> been a good girl?'<43><4E>Rosa:'Saro....'<44><4E>Saro:'Rosa,I've<43> decided to<43> exterminate all of<43> mankind.'<44><4E>Saro:'The world will<43> soon see its end.'<44><4E>Saro:'Until my<43> ambition is<43> fulfilled,you stay<43> here....'<44>
; Text $0436: <4E>Rosa:'Wait,Saro!'<44><4E>Rosa:'.........'<44>
; Text $0437: <4E>Rosa:'Someone...someone<43> must stop Saro!'<44><4E>Rosa:'Or the world<43> will cease to exist....'<44><4E>Rosa:'Please.... Someone.... Listen to me....'
; Text $0438: <4E>Rosa:'Someone.... Listen to me....'<43><4B><4B>
; Text $0439: 'You bold thieves!'<4F>You're under arrest! Come!'
; Text $043A: 'Get out! The Queen will see you.'
; Text $043B: 'I'm the Queen of this country.I judge all accused.'<4F>You're accused of stealing the prophetess's Bronze Amulet.'<4F>Do you admit you stole it?'
; Text $043C: 'Don't try to get away with a lighter sentence by simply confessing.'<4F>You're on trial.You must tell the truth.'<4F>I ask you again.Did you steal the Bronze Amulet?'
; Text $043D: 'The prophetess says she saw you steal it.'<4F>Do you still insist you didn't steal it?'
; Text $043E: 'Then who stole the Bronze Amulet?'<4F>If you insist you're falsely accused,I'll give you a chance to find the real thief.'<4F>However,I'll have to keep one of you as a hostage.'<4F>Soldiers! Put one of them into jail!'<4F>Go find the thief now!'
; Text $043F: 'That's different from what you said!'<4F>I'll ask you again.'<44>
