; Huffman-compressed text group(s): $22
; Text $0440: 'We've taken <50> as hostage.'<44>
; Text $0441: 'To change the hostage,talk to me.'
; Text $0442: 'Do you want to change the hostage?'
; Text $0443: 'Who will be the hostage?'
; Text $0444: 'Mercy on me! I admit my wrongdoing!'
; Text $0445: 'Splendid,<49>!'<4F>The Queen ordered me to follow you.'<4F>She instructed me to offer assistance if necessary.'<4F>I'll take him to the Castle.'<4F><49>,you return to the Castle.Bye!'
; Text $0446: 'Yummm! A delicious looking human!'
; Text $0447: 'You jail breaker!'
; Text $0448: 'You crook!'
; Text $0449: Saro:'Everyone! Something terrible has just happened at Aktemto!'<44>Saro:'Esturk,the Ruler of Evil,seems to have revived!'<44>Saro:'It seems men dug too deep and reached the Evil World.'<44>Saro:'We must go to Aktemto now! We'll bring Esturk the Great to our Castle!'<44><58><4B>Necrosaro chants Return!
; Text $044A: 'Thieves! Help!'
; Text $044B: 'Huh? It's you!'<44>'No way! You can't catch me!'
; Text $044C: <49>
; Text $044D: 'We've taken <49> as hostage.'
; Text $044E: 'I believe <49> is indispensable to you....'<4F>I'll take someone else.'
; Text $044F: 'No! I...<4B>I'm not tasty!'
; Text $0450: 'I'm too skinny.I know the person in the next room will taste better.'
; Text $0451: 'Help! <4B>Somebody help me!'
; Text $0452: Stairs appear before you.
; Text $0453: <49> plays the Flute of Uncovering.
; Text $0454: You can't talk this way!<44>Use TACTICS Command to change members.
; Text $0455: 'Huh? It's you!'<4F>No! <4B>You won't catch me!'
; Text $0456: Necrosaro:'I can't believe it! Esturk the Great was destroyed!'<44>Necrosaro:'According to the prophecy,only the Hero,a descendant of Zenithians,is capable of defeating the Ruler!'<44>Necrosaro:'Are you...are you the...!?'
; Text $0457: 'Necrosaro! We have bad news!'<4F>Your Rosa,the elfin girl,has been abducted by humans!'<44>Necrosaro:'What?'<44>Necrosaro:'Curses! Everyone! We must return to our base!'
; Text $0458: <50> goes out ahead and gets in the wagon!
; Text $0459: Alena:'Brey! You're back safely!'<44>
; Text $045A: Alena:'I couldn't find the Padequia Root.'
; Text $045B: Alena:'What? You found the Padequia Root?'<44>Alena:'I tried myself but couldn't find it.I'm impressed,Brey!'<44>
; Text $045C: <49>:'.........!'<44>
; Text $045D: Cristo:'I heard Necrosaro destroyed the Hero's village.Is <49> the...?'<44>Alena:'Really? Then we should journey together.'<44>Alena's party joined the Hero's Party!<43><55><44>They go out ahead and get in the wagon.
; Text $045E: Brey:'Princess,about that....'<44>Alena:'What? <4B>Are you sure? Someone else is also searching for Necrosaro?'<44>
; Text $045F: Alena:'I'd like to see them.Would you please bring them?'
