; Huffman-compressed text group(s): $23
; Text $0460: Alena:'Brey told me that <49> is searching for Necrosaro.Is that right?'<44>
; Text $0461: A voice is heard....<4F>This is Zenithian Tower.Only those who are eligible can enter....'<4F>Leave!'
; Text $0462: A mysterious force revives Lucia!<44>
; Text $0463: Lucia:'Thanks to you,I'm back in Zenithian Castle!'<44>Lucia:'I have to let everyone know I'm back.'<44>Lucia:'See you later!'
; Text $0464: 'Kekiki! You shouldn't turn your back on an enemy,you fool!'
; Text $0465: 'Gasp!'<43><51><4B>
; Text $0466: <41>One of the shields seems to have broken....
; Text $0467: 'Uggg....How devastated Necrosaro was after losing Rosa!'<4F>All mankind deserves to be exterminated....Glory to Necrosaro! <4B>Gasp!'<43><51><4B>
; Text $0468: 'Kkkk....You're good,I admit....'<4F>Enjoy your moment of glory.'<4F>But remember the ever evolving Necrosaro will destroy you all.'<4F>Wa,Ha,Ha! <4B>Gufff!'<43><51><4B>
; Text $0469: 'How I regret....'<4F>My curse on you....<4B>Gafff!'<43><51><4B>
; Text $046A: 'Gaahhh...!'<4F>Who are you? I'm Necrosaro.I have just awoke as the Ruler of Evil.'<4F>Urrggg...! Can't remember anything....'<4F>But I know what I need to do.'<4F>Gawaaa...! I must exterminate you all!'
; Text $046B: 'Guaarrr...!'<4F>Is this my end? I'm burning...my body is melting away....'<4F>Ugrrr.........!'
; Text $046C: <49> receives the Fire of Serenity from <49> and throws it into the fire.
; Text $046D: Lucia:'Come here,Doran!'
; Text $046E: Lucia:'Take Doran with you.He'll be a good help.'<44>
; Text $046F: Doran joined the Party!<43><55><44>
; Text $0470: Doran goes out ahead and gets in the wagon!<44>
; Text $0471: Lucia:'Good luck to you all!'
; Text $0472: 'Ahh! <4B>It's mother! Hurray!'
; Text $0473: Please place your wager.You can bet from 1 to 100 coins.
; Text $0474: Select the cards you want to HOLD.Then press DEAL.
; Text $0475: Congratulations! You've won <47> coin<4C>.
; Text $0476: If you win,you will get <47> coin<4C>.
; Text $0477: Will you try Double-or-Nothing No.<47>?
; Text $0478: Select a higher card than this from the 4 cards.
; Text $0479: It's a tie! Try again.
; Text $047A: Sorry,you've lost.
; Text $047B: Do you want to play again?
; Text $047C: You don't have any coins.Please come back after buying some.
; Text $047D: 'Alena,do you want to use your Medical Herb before the next match?'
; Text $047E: 'Do you want to use more Medical Herb?'
; Text $047F: 'Alena,you don't have any Medical Herb!'<44>
