; Huffman-compressed text group(s): $24
; Text $0480: 'Step right up! Witness the breathtaking fights among monsters from all countries!'<4F>Pick the winning monster,and you'll rake in the coins!'<44>
; Text $0481: 'For each fight,you can bet from 1 to 50 coins.How much do you want to wager?'
; Text $0482: 'You don't have enough coins.Come back after buying more.'
; Text $0483: 'Gufff!'
; Text $0484: 'On <50>,
; Text $0485: 'Are you leaving? Come back again!'
; Text $0486: <49> comes out the winner!
; Text $0487: 'Sorry,you've lost.'<44>
; Text $0488: 'Congratulations! You've won <47> coin<4C>.'<44>
; Text $0489: 'Here's the next fight's monsters and their odds.Which monster do you want bet on?'
; Text $048A: 'You can't pass up this fight.Which monster do you want to bet on?'
; Text $048B: To insert a coin,press UP on the Control Pad.To start,press the A Button.
; Text $048C: If you press the A Button,the reels will stop spinning starting from left to right.
; Text $048D: 'Oh,Soldier,please find our children!'<4F>They're alive! I know it!'
; Text $048E: 'Bye...real princess....'
; Text $048F: Do you want to play the slot machine one more time?<43>      YES   NO<40>
; Text $0490: <44>'I don't think this will produce any special effect when used as item in battle.'
; Text $0491: <44>'Furthermore,I think this will produce some special effect when used as item in battle.'
; Text $0492: <44>'You should be able to defeat any monster by penetrating its vital spot with this.'
; Text $0493: <44>'So this is the Zenithian Sword! I was expecting something more spectacular....'
; Text $0494: <44>'Look at it glow! This sword is something,after all!'
; Text $0495: <44>'What cute clothes!'
; Text $0496: <44>'Equipped with this,I think you'll lessen damage from fires.'
; Text $0497: <44>'Equipped with this,I think you'll lessen damage from spells.'
; Text $0498: <44>'I don't know what to tell you.'
; Text $0499: <44>'Equipped with this,I think you'll lesson the chance of being confused.'
; Text $049A: <44>'Should increase Agility.'
; Text $049B: <44>'Should increase Luck.'
; Text $049C: <44>'Must be a medicine.'
; Text $049D: <44>'Should repel weak monsters.'
; Text $049E: <44>'This flies you to the destination of your choice!'
; Text $049F: <44>'This revives anyone!'
