; Huffman-compressed text group(s): $25
; Text $04A0: <44>'This ends paralysis!'
; Text $04A1: <44>'I think this restores MP.'
; Text $04A2: <44>'I think this restores everyone's HP at once.'
; Text $04A3: <44>'I think this produces some special effect if used in battle.'
; Text $04A4: <44>'I think this releases a scent monsters love.'
; Text $04A5: <44>'But it seems it can only be used effectively once a day.'
; Text $04A6: <44>'I think this increases Strength.'
; Text $04A7: <44>'This increases the Maximum HP!'
; Text $04A8: <44>'This increases the Maximum MP!'
; Text $04A9: <44>'Hmm...A mysterious object.'
; Text $04AA: <44>'Looks delicious! I'm sure you'll feel better if you eat this.'
; Text $04AB: <44>'What awful hand writing! Only I can read something like this.Ehem!'
; Text $04AC: <44>'Phew! I can't stand it!'
; Text $04AD: 'I'm Ruvas.They called the armor I wore the Zenithian Armor.'<4F>Somebody stole it.'
; Text $04AE: 'Oh,you've found my armor!'<4F>I'll give it to you.Use it to save the world!'
; Text $04AF: Hector:'Excuse me,everyone!'<44>Hector:'I know I must take over my father's inn someday.'<44>Hector:'I've decided to study management under Old Howden.'<44>Hector:'Goodbye,Primrose! Goodbye,everyone! Best of luck!'<44>Hector left the Party!
; Text $04B0: 'I'm Master Dragon.I oversee the world from this Castle.'<44>
; Text $04B1: <49> revives!<44>
; Text $04B2: 'The friendship which has grown among you during this journey is so firm,no one can ruin it.'<4F><49>,I assure you.'
; Text $04B3: 'I collect Small Medals from all over the world.'<4F>I reward those who bring them to me.'
; Text $04B4: 'I collect Small Medals from all over the world.'<44>
; Text $04B5: 'You brought some Small Medals? You can give them to me.'<44>
; Text $04B6: 'I'm keeping your <47> Small Medal<4C>.Is there anything you want?'
; Text $04B7: 'What do you want?'
; Text $04B8: 'The <48>.Is that correct?'
; Text $04B9: 'Sorry but I can't give you that unless you bring more Small Medals.'<44>
; Text $04BA: 'You want the <48>,right?'<44>
; Text $04BB: 'Who will take it?'
; Text $04BC: 'Very well.I will give you some choices.'<44>
; Text $04BD: 'But <49> can't carry any more things.'<4F>Will anyone else take it?'
; Text $04BE: 'Do you want anything else?'
; Text $04BF: 'Come back anytime!'
