; Text $04C0: '<49>,the Hero,a Zenithian and human descendant!'<4F>Thanks to you and your friends,the Secret of Evolution,along with Necrosaro,has been driven deep down into the abyss of the world.'<4F>With the threat gone,peace will rule the world again!'<4F>The Eight Chosen Ones! I thank each one of you.'<4F>Ragnar,your performance was splendid.'<4F>Alena,you've performed with bravery and courage.'<4F>Brey and Cristo,I commend your devotion to Alena and your contribution to the quest.'<4F>Mara and Nara,I'm sure your father would be proud of you!'<4F>Taloon,continue to benefit the world and its people with your genius in trade.'<4F>And <49>!'<4F>You've proven to be an extraordinary leader! You won't have to return to the earth.'<4F>I shall allow you to live with us in this Zenithian Castle.'<4F>Eh? <4B>What's wrong?'<4F>You wish to return to the earth with them? Hmm....'<4F>Very well.I'll honor your wish.'<44>
; Text $04C1: The Giant Statue,Colossus,begins moving!
; Text $04C2: It seems the combined strength of 3 people is necessary to break the door open.
; Text $04C3: There is a lever.Do you want to pull it?
; Text $04C4: 'The ones you saw upstairs were our imposters.'<4F>There's no hope of escape...'<4F>for YOU!'
; Text $04C5: 'The next fight will begin shortly.Do you want to play again?'
; Text $04C6: But the Leaf of World Tree doesn't come off!
; Text $04C7: 'Since you've won over 10000 coins,we must stop now.'
; Text $04C8: Hector:'Hello! It's me,Hector!'<4F>Hector:'See? I'm working hard!'<44>
; Text $04C9: <50>:'.........'
; Text $04CA: You can't pass up this fight.
; Text $04CB: 'DO NOT PROCEED ANY FURTHER....LEAVE....'<44>
; Text $04CC:  <47> coin<4C>,right?<43> Now watch the fight.'
; Text $04CD: Cristo:'I'd like to meet too.'
; Text $04CE: 'Cry! Shed Ruby Teardrops!'<4F>Cry harder! Harder!'
; Text $04CF: Necrosaro:'Rosa!'<44>Necrosaro:'You! What have you done to her?'
; Text $04D0: Rosa:'Sa...<4B>Sar...<4B>Saro...<4B>you've...<4B>come for me....'<44>Rosa:'Please listen to my last words....'<44>Rosa:'Give...please...give up your obsession and come with me....Aaah!'
; Text $04D1: Necrosaro:'R...Rosa!'<44>Necrosaro:'.........'<44>Necrosaro:'Those humans! I will let them suffer for this! I promise!'
; Text $04D2: 'Princess Alena,I thank you for winning!'<4F>I know your father,the King of Santeem,will be proud of you.'<4F>Perhaps you should return home and let him know you're alive and well.'
; Text $04D3: 'This is my horse,Primrose.Everyone,be nice to her,OK?'<4F>Let's go!'
; Text $04D4: A voice is heard....<4F>This is Zenithian Castle.Only those who are eligible can enter.'<4F>Leave!'
; Text $04D5: 'You can't take any more coins.'<4F>We look forward to your next visit.'
